#!/usr/bin/env python3
"""Build guide 04; reuse sanitized screenshots, never access a customer account."""
from build_dealer_guides import Guide, ROOT, CW, M, H, HELP, MUTED
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from PIL import Image


def main():
    pdfmetrics.registerFont(TTFont('Body','/System/Library/Fonts/Supplemental/Arial.ttf'))
    pdfmetrics.registerFont(TTFont('Bold','/System/Library/Fonts/Supplemental/Arial Bold.ttf'))
    pdfmetrics.registerFontFamily('Body',normal='Body',bold='Bold')
    g=Guide(4,'documents','Ваші документи: перегляд, рахунок на оплату, повтор замовлення',6,'25.09.2026')

    g.page('Ваші документи в одному кабінеті','Оптовим партнерам: де шукати, що перевіряти та як використати знову.')
    g.step(1,'Увійдіть у свій кабінет','У меню є два різні розділи. <b>«Замовлення»</b> - ваші замовлення на сайті (WooCommerce). <b>«Документи ФОЛІО»</b> - документи нашої облікової системи, тобто нашої бази.')
    g.shot('cabinet','Два розділи поруч. У тексті цієї пам’ятки «наша база» означає розділ «Документи ФОЛІО».',[(.005,.44,.12,.24),(.54,.44,.16,.24)])
    g.table([
      ['<b>Що шукаєте</b>','<b>Куди перейти</b>'],
      ['Замовлення, яке оформили на сайті','«Замовлення»: номер, статус, товари, сума, складські частини й доступні дії. Тут також зберігаються чернетки.'],
      ['Рахунок, накладну або платіж','«Документи ФОЛІО»: документи нашої бази за вашим контрагентом, не лише нові покупки через сайт.'],
      ['Скільки залишилося сплатити','«Баланс із клієнтом»: підсумок взаєморозрахунків та деталізація операцій.'],
    ],[180,CW-180])
    g.note('Два номери не означають дві покупки','Номер замовлення сайту й номер документа нашої бази можуть відрізнятися. Після розділення по складах одне оформлення може мати кілька пов’язаних замовлень і документів.')
    g.link('Відкрити замовлення сайту','/my-account/orders/')
    g.link('Відкрити документи нашої бази','/my-account/folio-documents/')

    g.page('Знайдіть потрібний документ','Рахунки, видаткові накладні та платежі - окремі типи документів.')
    g.step(2,'Вкажіть дати й тип документа','Відкрийте «Документи ФОЛІО». Задайте початок і кінець періоду, залиште потрібні типи й натисніть <b>«Показати документи»</b>. Один запит охоплює до 366 днів; давніші документи шукайте окремими періодами.')
    g.shot('documents-filter','1 - дати; 2 - типи; 3 - кнопка показу. Особисті дані на фото приховані.',[(.015,.54,.32,.18),(.335,.40,.315,.31),(.80,.49,.185,.24)])
    g.table([
      ['<b>Тип</b>','<b>Для чого дивитися</b>'],
      ['Рахунок','Перевірити погоджені позиції та суму, скачати рахунок на оплату. Сам рахунок не доводить, що гроші вже отримані.'],
      ['Видаткова накладна','Переглянути документ відпуску товару: позиції, кількості, ціни та суму.'],
      ['Платіж','Перевірити зареєстровану оплату та доступний розподіл за документами. Це не список товарів для повторної покупки.'],
    ],[135,CW-135])
    g.step(3,'Натисніть «Переглянути»','У списку звірте номер, дату, суму й склад. Кнопка - праворуч у рядку; якщо не видно, прокрутіть таблицю вправо. Нижче відкриються деталі.')
    g.note('Якщо список порожній','Розширте дати та перевірте вибрані типи. Показуються активні документи; архівні сюди не входять. Якщо розділу немає або видно не ваші дані - зверніться до менеджера.')
    g.link('Перейти до списку документів','/my-account/folio-documents/')

    g.page('Прочитайте деталі та зв’язок','Документ нашої бази показує результат, а не лише факт натискання «Замовити».')
    g.step(4,'Звірте реквізити й товари','Угорі перевірте номер, дату, суму, склад і поле «Враховується в обліку». Нижче - артикули, назви, кількості, історичні ціни й суми рядків. Посилання на назву товару відкриває його картку, якщо товар знайдений на сайті.')
    g.shot('document-header','Приклад зв’язку: замовлення сайту №117786 → рахунок нашої бази №555314.',[(.33,.105,.28,.22),(.66,.33,.31,.22),(.33,.78,.33,.20)])
    g.text('У цьому прикладі номер замовлення сайту є в полі <b>«Інфо»</b>. Не всі документи походять із сайту, тому такий зв’язок може бути відсутній.',10.5)
    g.step(5,'Перевірте оплати та складські частини','Якщо дані передані з бази, нижче з’являться <b>пов’язані платежі</b> й <b>розподіл оплат</b>. Для загальної суми до сплати відкрийте баланс. Сума документа не дорівнює автоматично залишку боргу.')
    g.note('Після розділення замовлення','У «Замовленнях» відкрийте дочірні частини: кожна може мати свій склад і документ. У загального замовлення колонка «ФОЛІО» може містити «—». Це не помилка. Не сплачуйте кожну частину повторно без узгодження.')
    g.note('Документ без складського руху','Необліковий документ на складі 7 із позначкою «нет на складе» фіксує потребу. Він не резервує, не списує й не переміщує товар і не підтверджує відвантаження.')
    g.link('Перевірити свій баланс','/my-account/folio-balance/')

    g.page('Скачайте рахунок на оплату','Почніть із рахунка або видаткової накладної нашої бази.')
    g.step(6,'Натисніть «Рахунок XLSX»','Відкрийте потрібний документ через «Переглянути». У блоці «Рахунок на оплату» натисніть <b>«Рахунок XLSX»</b> і дочекайтеся завантаження. Відкрийте файл у програмі для таблиць; за потреби роздрукуйте звідти.')
    g.shot('document-export','Кнопка зліва завантажує файл, кнопка справа надсилає його на вказану адресу.',[(.006,.58,.156,.37),(.795,.58,.197,.37)])
    g.text('У файлі - всі позиції, артикули, доступні штрихкоди, кількості, історичні ціни й суми документа. Порожній штрихкод означає, що перевіреного значення немає; штрихкоди беруться з поточного каталогу.',10.5)
    g.step(7,'Або надішліть рахунок на email','Перевірте адресу в полі «Email отримувача»: за замовчуванням це адреса профілю, її можна замінити. Натисніть <b>«Надіслати на email»</b> один раз. Дочекайтеся повідомлення, перевірте пошту та «Спам».')
    g.note('Перед надсиланням перевірте адресата','Лист містить ваш документ із товарами, цінами та сумами. Підтвердження прийняття поштовою службою ще не гарантує доставку. Після невизначеної помилки спочатку перевірте пошту, а не натискайте багато разів.',True)
    g.note('Файл - на повну суму документа','Вже внесені оплати не віднімаються від суми «Рахунок XLSX». Залишок до сплати перевіряйте в балансі. Завантаження не створює нового документа й не змінює старого.')
    g.text('<b>Кнопки немає?</b> Для платежів і повернень такий рахунок не формується. Якщо суми неповні, файл не створився або потрібні реквізити відсутні, зверніться до менеджера.',10.5)
    g.link('Докладно про документи й рахунок',HELP+'#folio')

    g.page('Повторіть товари або збережіть файл','Стара покупка - зручна основа для нового замовлення.')
    g.step(8,'Виберіть тільки потрібні позиції','У деталях рахунка або накладної знайдіть блок повторного замовлення. За замовчуванням позначені всі доступні рядки: зніміть зайві позначки. Натисніть «Додати вибрані позиції до кошика» або «Зберегти вибрані позиції як чернетку».')
    g.shot('document-repeat','Позначки визначають товари; дві кнопки внизу - спосіб продовжити роботу.',[(.012,.55,.05,.15),(.008,.817,.70,.13)])
    g.text('<b>У кошик:</b> товари додаються до наявних, кошик не очищається. Перевірте звіт про додані/пропущені рядки, кількість і склад, потім оформіть замовлення.<br/><b>У чернетку:</b> створюється окремий список, кошик не змінюється. Чернетка не резервує товар. Платежі та повернення не є шаблонами повторної покупки.',10.3)
    g.text('<b>Стара ціна - лише історія.</b> Нова покупка використовує актуальну ціну, залишки та режим складу. Саме повторення товарів не змінює початковий документ.',10.3)
    g.note('Не натискайте повторно після незрозумілого результату','Спочатку перевірте кошик або розділ чернеток. Якщо товари вже додалися, повторна дія може збільшити кількість. За потреби передайте менеджеру номер документа й текст повідомлення.',True)
    g.link('Відкрити кошик і перевірити результат','/cart_lh_klassick/')
    g.link('Відкрити збережені чернетки','/my-account/orders/')

    g.page('Збережіть список із замовлення','Експорт CSV/XLSX - для власного обліку або наступного імпорту.')
    g.step(9,'Збережіть замовлення сайту в CSV/XLSX','У «Замовленнях» відкрийте потрібне замовлення. У блоці експорту оберіть колонки та подання «Загальний» або «Окремо по складах», потім CSV чи XLSX. Файл містить збережені ціни цього замовлення; експорт нічого не очищає.')
    # Public screenshot from the canonical guide, clipped in PDF; no private data.
    path=ROOT/'docs/images/wholesale/import-to-cart-and-draft.jpg'
    iw,ih=Image.open(path).size
    sx,sy,sw,sh=175,149,1000,140
    scale=CW/sw; height=sh*scale
    g.c.saveState()
    clip=g.c.beginPath();clip.rect(M,H-g.y-height,CW,height)
    g.c.clipPath(clip,stroke=0)
    g.c.drawImage(str(path),M-sx*scale,H-g.y-(ih-sy)*scale,width=iw*scale,height=ih*scale)
    g.c.restoreState();g.y+=height+5
    g.text('Приклад блоку експорту в кошику з докладної інструкції. Експорт доступний і на сторінці замовлення.',8,MUTED,gap=15)
    g.table([
      ['<b>Налаштування</b>','<b>Що отримуєте</b>'],
      ['Колонки','Артикул, штрихкод, назва, кількість, ціна, сума та примітки - оберіть потрібне.'],
      ['Загальний','Один рядок товару; складський розподіл зазначений у примітці.'],
      ['Окремо по складах','Окремі рядки для складських частин товару.'],
      ['CSV або XLSX','Файл на ваш комп’ютер. Якщо XLSX тимчасово недоступний, скористайтеся CSV.'],
    ],[145,CW-145])
    g.text('<b>Експорт списку ≠ рахунок на оплату.</b> Для рахунка використовуйте «Рахунок XLSX» у нашій базі (сторінка 4). Експортований список можна знову імпортувати; сайт перевірить актуальні ціни й наявність.',10.3)
    g.note('Замовлення не видно або потрібне виправлення?','Перевірте свій обліковий запис; якщо сайт просить підтвердити email, виконайте підтвердження через власну пошту. Старі документи не виправляються повторним замовленням. Для коригування зверніться до менеджера з номером і датою документа.')
    g.link('Експорт та повторне використання файлів',HELP+'#eksport')
    g.link('Повна інструкція у вашому кабінеті',HELP)
    g.save()


if __name__=='__main__':
    main()
